import { spawn } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import AdmZip from 'adm-zip';
/** The platform manifest gate requires `sanityID` to be exactly 36 characters. */
export const SANITY_ID_LENGTH = 36;
/** Derive a stable 36-char `sanityID` from the project scope id (UUID-shaped hash). */
export function deriveSanityId(scopeId) {
    const hex = crypto.createHash('sha256').update(scopeId).digest('hex');
    return [
        hex.slice(0, 8),
        hex.slice(8, 12),
        hex.slice(12, 16),
        hex.slice(16, 20),
        hex.slice(20, 32),
    ].join('-');
}
/** Build the manifest from the resource and project scope. */
export function buildAgentManifest(resource, scopeId) {
    const manifest = {
        sanityID: deriveSanityId(scopeId),
        name: resource.name,
        region: resource.region,
    };
    if (typeof resource.description === 'string' && resource.description.length > 0) {
        manifest.description = resource.description;
    }
    return manifest;
}
// The Web Function runtime loads this root index.mjs and expects an HTTP
// listener on AWS_LAMBDA_HTTP_ENDPOINT. eve's node-server reads HOST/NITRO_HOST/
// PORT/NITRO_PORT, so map the endpoint onto those before importing the server.
// Only /tmp is writable, so point eve's data root there: eve resolves its
// workflow data dir as join(process.cwd(), '.eve/.workflow-data'), so create
// that full path, set the explicit override, and chdir so the join lands under
// the writable root rather than the read-only /var/task.
const WEB_FUNCTION_ENTRY = `import {mkdirSync} from 'node:fs'
const endpoint = process.env.AWS_LAMBDA_HTTP_ENDPOINT || '0.0.0.0:3000'
const sep = endpoint.lastIndexOf(':')
const host = sep > 0 ? endpoint.slice(0, sep).replace(/^\\[|\\]$/g, '') : '0.0.0.0'
const port = sep > 0 ? endpoint.slice(sep + 1) : '3000'
process.env.HOST = host
process.env.NITRO_HOST = host
process.env.PORT = port
process.env.NITRO_PORT = port
const dataRoot = process.env.EVE_DATA_ROOT || '/tmp/eve-data'
process.env.EVE_DATA_ROOT = dataRoot
const workflowDataDir = dataRoot + '/.eve/.workflow-data'
mkdirSync(workflowDataDir, {recursive: true})
process.env.WORKFLOW_LOCAL_DATA_DIR = workflowDataDir
process.chdir(dataRoot)
await import('./.output/server/index.mjs')
`;
// Resolve the eve CLI from the agent's own install so its pinned version runs.
// eve's exports map blocks the bin subpath, so resolve its package.json and read
// the bin field rather than require.resolve('eve/bin/eve.js').
function resolveEveBin(agentPath) {
    const require = createRequire(path.join(agentPath, 'noop.js'));
    try {
        const pkgPath = require.resolve('eve/package.json');
        const pkg = require('eve/package.json');
        const bin = typeof pkg.bin === 'string' ? pkg.bin : pkg.bin?.eve;
        if (!bin)
            throw new Error('eve package has no bin entry');
        return path.join(path.dirname(pkgPath), bin);
    }
    catch {
        throw new Error(`eve is not installed for the agent at ${agentPath}. ` +
            'Run `npm install` in the agent project so `eve build` can run.');
    }
}
function runEveBuild(agentPath) {
    const eveBin = resolveEveBin(agentPath);
    return new Promise((resolve, reject) => {
        const child = spawn(process.execPath, [eveBin, 'build'], { cwd: agentPath });
        let output = '';
        child.stdout?.on('data', (d) => {
            output += d;
        });
        child.stderr?.on('data', (d) => {
            output += d;
        });
        child.on('error', reject);
        child.on('close', (code) => {
            if (code !== 0) {
                reject(new Error(`eve build failed for ${agentPath} (exit code ${code}).\n${output.trim()}`));
                return;
            }
            const outputDir = path.join(agentPath, '.output');
            const serverEntry = path.join(outputDir, 'server', 'index.mjs');
            if (!fs.existsSync(serverEntry)) {
                reject(new Error(`eve build did not produce ${serverEntry}.\n${output.trim()}`));
                return;
            }
            resolve(outputDir);
        });
    });
}
/** Seam so tests can supply a fixture `.output` instead of a real build. */
export const eveBuild = { run: runEveBuild };
/**
 * Assemble the Web Function bundle for a `sanity.agent` resource: a runnable
 * root `index.mjs` bootstrap, eve's built node-server under `.output/`, and the
 * root `package.json` manifest. Asset prep is the sole producer; the Provider
 * only reads the bytes, so the layout is complete here.
 */
export async function buildAgentPackage(agentPath, manifest, build = eveBuild.run) {
    const outputDir = await build(agentPath);
    const zip = new AdmZip();
    zip.addFile('index.mjs', Buffer.from(WEB_FUNCTION_ENTRY, 'utf8'));
    zip.addLocalFolder(outputDir, '.output');
    zip.addFile('package.json', Buffer.from(JSON.stringify(manifest, null, 2), 'utf8'));
    // Zero entry times so identical inputs hash identically and the stash reuses
    // the asset.
    for (const entry of zip.getEntries())
        entry.header.time = new Date(0);
    return zip;
}
